import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    root = {}
    pos = 1
    for _ in range(n):
        path, val = data[pos], data[pos + 1]
        pos += 2
        keys = path[1:].split('.')
        node = root
        for key in keys[:-1]:
            node = node.setdefault(key, {})
        node[keys[-1]] = val
    q = int(data[pos])
    pos += 1

    def ser(node):
        if isinstance(node, str):
            return node
        return '{' + ','.join(k + ':' + ser(v) for k, v in node.items()) + '}'

    def walk(node, segs, i, res):
        if i == len(segs):
            res.append(node)
            return
        if not isinstance(node, dict):
            return
        s = segs[i]
        if s == '*':
            for child in node.values():
                walk(child, segs, i + 1, res)
        else:
            child = node.get(s)
            if child is not None:
                walk(child, segs, i + 1, res)

    out = []
    for _ in range(q):
        segs = data[pos][1:].split('.')
        pos += 1
        res = []
        walk(root, segs, 0, res)
        if '*' in segs:
            out.append('[' + ','.join(ser(r) for r in res) + ']')
        else:
            out.append(ser(res[0]) if res else 'null')
    print('\n'.join(out))

